import openpyxl
wb = openpyxl.load_workbook('/data/sahyog_budget_and_receipts.xlsx', data_only=True)
ws = wb['Finance FY25-26']
budget = []
receipts = []
for row in ws.iter_rows(values_only=True):
    first = row[0]
    if isinstance(first, str):
        if first.startswith('BG-'):
            approved = row[4]
            if approved is not None:
                budget.append(approved)
        elif first.startswith('RCPT-'):
            amt = row[5]
            if amt is not None:
                receipts.append(amt)
print('budget count', len(budget), budget)
print('receipt count', len(receipts), receipts)
print('total budget', sum(budget))
print('total receipts', sum(receipts))
